python
def floorRegisterBossReceipt(root, k):
    a=root
    out=[]
    from collections import deque
    queue=deque([a] if a else [])
    while queue:
        s=0
        for _ in range(len(queue)):
            node=queue.popleft()
            s+=node.val
            if node.left: queue.append(node.left)
            if node.right: queue.append(node.right)
        out.append(s)
    return sum((i+1)*x for i,x in enumerate(out))


