class Solution {
  public int floorRegisterBossReceipt(TreeNode root, int k) {
    TreeNode a=root; List<Integer> out=new ArrayList<>();
    {if(a!=null){Deque<TreeNode>queue=new ArrayDeque<>();queue.add(a);while(!queue.isEmpty()){int count=queue.size(),s=0;while(count-->0){TreeNode node=queue.remove();s+=node.val;if(node.left!=null)queue.add(node.left);if(node.right!=null)queue.add(node.right);}out.add(s);}}}
    int answer=0;for(int i=0;i<out.size();i++)answer+=(i+1)*out.get(i);return answer;
  }
}
